    s = sys.stdin.readline().strip()
    n_line = sys.stdin.readline().strip()
    if not n_line:
        return
    n = int(n_line)

    len_s = len(s)

    if n > len_s:
        min_val = (len_s + n) // 2
    else:
        min_val = n
    max_val = (len_s + n) // 2

    def check(a):
        # a - n could be negative, range handles it correctly (empty)
        for i in range(1, a - n + 1):
            if s[len_s - i] != s[len_s - i - a]:
                return False
        return True

    temp = 0
    # Find max tandem repeat inside s
    for i in range(len_s):
        # j*2 + i <= len_s  => j <= (len_s - i) // 2
        max_j = (len_s - i) // 2
        for j in range(1, max_j + 1):
            # Check if s[i:i+j] == s[i+j:i+2*j]
            if s[i:i+j] == s[i+j:i+2*j]:
                if j > temp:
                    temp = j

    ans = 0
    for i in range(max_val, min_val - 1, -1):
        if check(i):
            ans = i
            break

    if min_val > ans:
        ans = min_val
    if temp > ans:
        ans = temp

    print(2 * ans)

if __name__ == "__main__":
    solve()
